});

corrected_code:
router.post('/real-estate/leases/:leaseId/signatures/request', requireAuth, async (ctx) => {
  const { leaseId } = ctx.params;
  const { signerEmail, signatoryRole } = ctx.request.body;

  const lease = await LeaseContract.findOne({
    where: {
      id: leaseId,
      landlordId: ctx.state.user.id
    }
  });
  if (!lease) {
    ctx.status = 403;
    ctx.body = { error: 'Forbidden: you are not the landlord for this lease agreement' };
    return;
  }

  const envelope = await eSignService.sendSigningInvitation({
    documentUrl: lease.documentPdfUrl,
    recipientEmail: signerEmail,
    role: signatoryRole
  });

  await lease.update({ status: 'AWAITING_SIGNATURES', lastEnvelopeId: envelope.id });
  ctx.body = { success: true, envelopeId: envelope.id };
});
